import { DndContext, useDraggable, useDroppable, type DragEndEvent } from '@dnd-kit/core'
import { useEffect, useState } from 'react'
import { Button } from '../../components/Button'
import { Card } from '../../components/Card'
import { InventoryCompareModal } from '../../components/InventoryCompareModal'
import { activeTrip, addItineraryItem, getInventory, getItinerary, notifyTripUpdated, removeItineraryItem, reorderItinerary, swapItineraryItem, updateItineraryItem, type ApiItem, type InventoryItem, type WalletSummary } from '../../services/tripService'

// What the currently-open comparison modal is for: swapping a specific live item, or adding a
// brand-new one. Kept alongside the candidate list so the "Choose this" handler knows which
// itinerary mutation to call once the traveler picks a card.
type CompareAction = { kind: 'swap'; item: ApiItem } | { kind: 'add' }

function DragCard({ item }: { item: ApiItem }) { const { attributes, listeners, setNodeRef, transform } = useDraggable({ id: item.id }); return <div ref={setNodeRef} style={transform ? { transform: `translate3d(${transform.x}px, ${transform.y}px, 0)` } : undefined}><Card className="canvas-activity"><button {...attributes} {...listeners} aria-label={`Drag ${item.title}`} className="canvas-drag-handle" type="button">⠿</button><div><span className="canvas-activity-type">{item.type}</span><h3>{item.title}</h3><p>{new Date(item.startTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} · {item.location}</p></div><strong>₹{item.cost.toLocaleString()}</strong></Card></div> }
function DropZone({ index }: { index: number }) { const { isOver, setNodeRef } = useDroppable({ id: `position-${index}` }); return <div className={`canvas-drop-position ${isOver ? 'is-over' : ''}`} ref={setNodeRef} /> }

export function CanvasPage() {
  const [items, setItems] = useState<ApiItem[]>([]); const [summary, setSummary] = useState<WalletSummary | null>(null); const [error, setError] = useState(''); const tripId = activeTrip.get()
  const [compareOpen, setCompareOpen] = useState(false); const [compareHeading, setCompareHeading] = useState(''); const [compareCandidates, setCompareCandidates] = useState<InventoryItem[]>([]); const [compareAction, setCompareAction] = useState<CompareAction | null>(null); const [compareBusyId, setCompareBusyId] = useState<string | null>(null)
  const load = () => { if (!tripId) return; void getItinerary(tripId).then(setItems).catch((reason) => setError(reason instanceof Error ? reason.message : 'Unable to load itinerary.')) }
  useEffect(() => { load(); window.addEventListener('trippilot:trip-updated', load); return () => window.removeEventListener('trippilot:trip-updated', load) }, [tripId])
  const reorder = async ({ active, over }: DragEndEvent) => { if (!over || active.id === over.id || !tripId) return; const target = Number(String(over.id).replace('position-', '')); const oldIndex = items.findIndex((item) => item.id === active.id); if (oldIndex < 0 || Number.isNaN(target)) return; const next = [...items]; const [moved] = next.splice(oldIndex, 1); next.splice(target, 0, moved); const base = new Date(next[0]?.startTime || new Date()); base.setHours(9, 0, 0, 0); const payload = next.map((item, index) => ({ id: item.id, startTime: new Date(base.getTime() + index * 3 * 3_600_000).toISOString(), endTime: new Date(base.getTime() + (index * 3 + 2) * 3_600_000).toISOString() })); try { const result = await reorderItinerary(tripId, payload); setItems(result.items); setSummary(result.summary); notifyTripUpdated() } catch (reason) { setError(reason instanceof Error ? reason.message : 'Unable to reorder itinerary.') } }
  const editTime = async (item: ApiItem) => { const value = window.prompt('New start time (YYYY-MM-DDTHH:mm)', item.startTime.slice(0, 16)); if (!value) return; const start = new Date(value); const end = new Date(start.getTime() + (new Date(item.endTime).getTime() - new Date(item.startTime).getTime())); try { const result = await updateItineraryItem(item.id, { startTime: start.toISOString(), endTime: end.toISOString() }); setItems((current) => current.map((entry) => entry.id === item.id ? result.item : entry)); setSummary(result.summary); notifyTripUpdated() } catch (reason) { setError(reason instanceof Error ? reason.message : 'Time change conflicts with your itinerary.') } }
  const remove = async (id: string) => { if (!window.confirm('Remove this experience?')) return; try { const result = await removeItineraryItem(id); setItems((current) => current.filter((item) => item.id !== id)); setSummary(result.summary); notifyTripUpdated() } catch (reason) { setError(reason instanceof Error ? reason.message : 'Unable to remove item.') } }
  // Loads verified inventory and narrows it to 2-3 comparable candidates (same type as the item
  // being swapped, cheapest first) so the modal can show them side by side instead of a
  // window.prompt numbered list.
  const openCompare = async (heading: string, action: CompareAction) => { if (!tripId) return; setError(''); try { const inventory = await getInventory(tripId); const pool = action.kind === 'swap' ? inventory.filter((entry) => entry.type === action.item.type) : inventory; const candidates = [...pool].sort((a, b) => a.price - b.price).slice(0, 3); setCompareHeading(heading); setCompareCandidates(candidates); setCompareAction(action); setCompareOpen(true) } catch (reason) { setError(reason instanceof Error ? reason.message : 'Unable to load comparable inventory.') } }
  const closeCompare = () => { setCompareOpen(false); setCompareAction(null); setCompareBusyId(null) }
  const swap = (item: ApiItem) => void openCompare('Swap with verified inventory', { kind: 'swap', item })
  const add = () => void openCompare('Add verified inventory', { kind: 'add' })
  const chooseCandidate = async (selected: InventoryItem) => {
    if (!compareAction || !tripId) return
    setCompareBusyId(selected.id); setError('')
    try {
      if (compareAction.kind === 'swap') { const result = await swapItineraryItem(compareAction.item.id, selected.id); setItems((current) => current.map((entry) => entry.id === compareAction.item.id ? result.item : entry)); setSummary(result.summary) }
      else { const start = new Date(items[items.length - 1]?.endTime || new Date()); start.setHours(start.getHours() + 1); const end = new Date(start.getTime() + 2 * 3_600_000); const result = await addItineraryItem(tripId, selected.id, start.toISOString(), end.toISOString()); setItems((current) => [...current, result.item]); setSummary(result.summary) }
      notifyTripUpdated(); closeCompare()
    } catch (reason) { setError(reason instanceof Error ? reason.message : compareAction.kind === 'swap' ? 'Unable to swap item.' : 'Unable to add inventory item.'); setCompareBusyId(null) }
  }
  return <DndContext onDragEnd={(event) => void reorder(event)}><section className="canvas-page"><div className="canvas-heading"><p className="eyebrow">Trip canvas</p><h1 className="page-title">Shape the flow.</h1><p className="page-copy">Drag verified activities to reorder them. Every update is checked for overlaps, trip dates, hotel conflicts, and budget impact.</p></div><Card className="canvas-budget"><div><span>Live trip spend</span><strong>₹{(summary?.planned ?? items.reduce((sum, item) => sum + item.cost, 0)).toLocaleString()}</strong><small>{summary ? `₹${summary.remaining.toLocaleString()} remaining` : 'Loading live budget…'}</small></div><div className="canvas-budget-meter"><span style={{ width: `${summary ? Math.min(100, (summary.planned / summary.budget) * 100) : 0}%` }} /></div><p>{summary?.budgetOverflow ? 'Budget guardrail exceeded — you may continue after review.' : 'Validated itinerary'}</p></Card>{error && <p className="auth-error">{error}</p>}<section className="canvas-activities"><header><span className="canvas-day-label">Live</span><div><h2>Verified itinerary</h2><p>{items.length} connected activities</p></div></header>{items.map((item, index) => <div className="canvas-live-item" key={item.id}><DropZone index={index} /><DragCard item={item} /><div className="canvas-inline-actions"><Button onClick={() => void editTime(item)} type="button" variant="ghost">Edit time</Button><Button onClick={() => void swap(item)} type="button" variant="ghost">Swap</Button><Button onClick={() => void remove(item.id)} type="button" variant="ghost">Remove</Button></div></div>)}<DropZone index={items.length} /><button className="canvas-empty-slot" onClick={() => void add()} type="button"><strong>＋ Add experience</strong><span>Choose from verified inventory.</span></button></section></section><InventoryCompareModal busyId={compareBusyId} candidates={compareCandidates} heading={compareHeading} isOpen={compareOpen} onChoose={(selected) => void chooseCandidate(selected)} onClose={closeCompare} /></DndContext>
}
